// Writes supabase/record-applied-migrations.sql from the files in supabase/migrations.
//
// Why it exists: the live database was built by pasting migration files into the Supabase
// SQL Editor, so the database's own list of applied migrations is empty. The first
// `supabase db push` would then try to run every migration again and fail (or worse,
// half-succeed). Running the generated file once records them all as applied.
//
//   npm run migrations:record          rewrite the file
//   node scripts/record-migrations.mjs --check    exit 1 if the file is out of date (used by a test)
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const migrationsDir = join(root, "supabase", "migrations");
const outFile = join(root, "supabase", "record-applied-migrations.sql");

const files = readdirSync(migrationsDir)
  .filter((f) => f.endsWith(".sql"))
  .sort();

const rows = files.map((file) => {
  const match = /^(\d{14})_(.+)\.sql$/.exec(file);
  if (!match) throw new Error(`Migration file name must look like 20261007120000_what_it_does.sql: ${file}`);
  const [, version, name] = match;
  return `  ('${version}', '${name.replace(/'/g, "''")}', '{}')`;
});

const sql = `-- GENERATED by scripts/record-migrations.mjs (npm run migrations:record). Do not edit by hand.
--
-- Run this ONCE in the Supabase SQL Editor, after every file in supabase/migrations has been
-- applied, if the database was built by pasting migrations by hand. It tells the Supabase CLI
-- they are already applied, so \`supabase db push\` will not try to run them again.
--
-- Safe to run again at any time: rows that already exist are skipped. After applying a new
-- migration by hand, run \`npm run migrations:record\` and paste the file again.

create schema if not exists supabase_migrations;

create table if not exists supabase_migrations.schema_migrations (
  version text not null primary key,
  statements text[],
  name text
);

insert into supabase_migrations.schema_migrations (version, name, statements) values
${rows.join(",\n")}
on conflict (version) do nothing;
`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(outFile, "utf8").replace(/\r\n/g, "\n");
  } catch {
    /* missing: reported below */
  }
  if (current !== sql) {
    console.error("supabase/record-applied-migrations.sql is out of date. Run: npm run migrations:record");
    process.exit(1);
  }
  console.log(`record-applied-migrations.sql lists all ${rows.length} migrations.`);
} else {
  writeFileSync(outFile, sql);
  console.log(`Wrote ${outFile} (${rows.length} migrations).`);
}
